def get_subscription_entity(
    sub_id: str = Path(...),
    db: Session = Depends(get_db)
) -> Subscription:
    sub = db.query(Subscription).filter(Subscription.stripe_subscription_id == sub_id).first()
    if not sub:
        raise HTTPException(status_code=404, detail="Subscription not found")
    return sub

@router.post("/billing/subscriptions/{sub_id}/cancel-renewal")
def cancel_subscription_renewal(
    subscription: Subscription = Depends(get_subscription_entity),
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    if subscription.customer_id != user.customer_id:
        raise HTTPException(status_code=403, detail="Subscription does not belong to current customer")
    subscription.auto_renew = False
    db.commit()
    return {"status": "cancelled", "subscription_id": subscription.stripe_subscription_id}
